function compute(inputs){
  const f = inputs.f;
  const fs = inputs.fs;
  const fN = 2 * f;
  const k = Math.round(f / fs);
  const fa = Math.abs(f - k * fs);
  const N = 200;
  const tmax = 1;
  const t = [];
  const x = [];
  const xa = [];
  for (let i = 0; i <= N; i++) {
    const ti = tmax * i / N;
    t.push(ti);
    x.push(Math.sin(2 * Math.PI * f * ti));
    xa.push(Math.sin(2 * Math.PI * fa * ti));
  }
  const sampleTimes = [];
  const sampleValues = [];
  const nSamples = Math.floor(fs * tmax);
  for (let n = 0; n <= nSamples; n++) {
    const tn = n / fs;
    sampleTimes.push(tn);
    sampleValues.push(Math.sin(2 * Math.PI * f * tn));
  }
  const series = {
    x: t,
    lines: [
      {name: 'Original x(t)', y: x},
      {name: 'Apparent x_a(t)', y: xa}
    ],
    marker: {x: sampleTimes, y: sampleValues}
  };
  const table = {
    columns: ['Quantity', 'Value'],
    rows: [
      ['f (Hz)', f.toFixed(2)],
      ['f_s (Hz)', fs.toFixed(2)],
      ['Nyquist rate 2f (Hz)', fN.toFixed(2)],
      ['k = round(f/f_s)', k],
      ['f_a = |f - k f_s| (Hz)', fa.toFixed(2)],
      ['Aliasing?', fs < fN ? 'Yes' : 'No']
    ]
  };
  let insight;
  if (fs >= fN) {
    insight = 'f_s = ' + fs.toFixed(1) + ' Hz ≥ 2f = ' + fN.toFixed(1) + ' Hz. No aliasing: f_a = f = ' + f.toFixed(1) + ' Hz.';
  } else {
    insight = 'f_s = ' + fs.toFixed(1) + ' Hz < 2f = ' + fN.toFixed(1) + ' Hz. Aliasing: f_a = ' + fa.toFixed(1) + ' Hz (k=' + k + ').';
  }
  return {
    series: series,
    table: table,
    f: f,
    fs: fs,
    fN: fN,
    fa: fa,
    k: k,
    insight: insight
  };
}
